import re,csv
def norm(t):
    t=re.sub(r'\[\[page \d+\]\]',' ',t)
    t=re.sub(r'\s+',' ',t)
    t=re.sub(r'([a-zåäö]) ?- (?!(?:ja|sekä|tai|eli|että|kuin|and|or)\b)([a-zåäö])',r'\1\2',t)
    return t
